public class Fehlerjagd {

    public static void main(String[] args) {
        int[] werte = {4, 8, 15};
        int summe = 0;

        for (int i = 0; i < werte.length; i++) {
            summe += werte[i];
            System.out.println("Debug: nach Wert " + werte[i] + " ist summe=" + summe);
        }
        System.out.println("Fertig. Summe=" + summe);
    }
}

