public class Spurensicherung {

    public static void main(String[] args) {
        int[] werte = {5, 10, 20};
        int summe = 0;

        for (int i = 0; i < werte.length; i++) {
            summe += werte[i];
            System.out.println("Schritt " + (i + 1) + ": summe=" + summe);
        }
        System.out.println("Summe: " + summe);
    }
}
